function ny_h($v){return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$error='';$relay=[];
if(($_SERVER['REQUEST_METHOD']??'')==='POST')try{
 if(empty($member['mb_id']))throw new DomainException('로그인 후 장바구니를 이용해 주세요.');
 if(($_SERVER['HTTP_ORIGIN']??'')!=='https://noastudio.ai.kr'||!is_string($_POST['csrf']??null)||!hash_equals($csrf,$_POST['csrf']))throw new DomainException('페이지를 다시 열어 주세요.');
 if(!is_string($_POST['items']??null)||strlen($_POST['items'])>8192)throw new DomainException('상품과 수량을 확인해 주세요.');$items=json_decode($_POST['items'],true,32,JSON_THROW_ON_ERROR);if(!is_array($items)||!array_is_list($items)||!$items||count($items)>50)throw new DomainException('상품을 선택해 주세요.');$seen=[];
 foreach($items as $r){$kind=$r['kind']??'';$sid=$r['sourceId']??'';$qty=$r['quantity']??0;if(!is_string($kind)||!is_string($sid)||!is_int($qty)||$qty<1||$qty>10)throw new DomainException('수량을 확인해 주세요.');$id=ny_id($kind,$sid);$p=$catalog[$id]??null;if(!$p||!$p['orderable']||isset($seen[$id]))throw new DomainException('옵션·배송 설정이 완료된 상품만 주문할 수 있습니다.');$seen[$id]=true;$it=ns_one('SELECT it_id,it_price,it_use,it_stock_qty,it_10 FROM '.ns_table('g5_shop_item_table').' WHERE it_id='.ns_e($id));if(!$it||(int)$it['it_use']!==1||(int)$it['it_price']!==$p['price']||$it['it_10']!=='noa:'.$kind.':'.$sid)throw new DomainException('상품 정보를 갱신하고 있습니다. 잠시 후 다시 시도해 주세요.');$relay[]=$p+['quantity'=>$qty];}
}catch(Throwable $e){$error=$e instanceof DomainException?$e->getMessage():'상품과 수량을 확인해 주세요.';}
